import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

enum BookingStatus { CONFIRMED, CANCELLED }

record RoomType(String roomTypeId, String displayName,
                int totalRooms, long basePriceCents,
                double overbookPercentage) {
    public int overbookedCapacity() {
        return (int) Math.floor(totalRooms * (1 + overbookPercentage));
    }
}

record Hotel(String hotelId, String name, String city,
             Map<String, RoomType> roomTypes) {}

class Hold {
    private final String holdId;
    private final String hotelId;
    private final String roomTypeId;
    private final LocalDate checkIn;
    private final LocalDate checkOut;
    private final int roomCount;
    private final String userId;
    private final Instant createdAt;
    private final Duration ttl;

    public Hold(String hotelId, String roomTypeId, LocalDate checkIn,
                LocalDate checkOut, int roomCount, String userId, Duration ttl) {
        this.holdId = UUID.randomUUID().toString();
        this.hotelId = hotelId;
        this.roomTypeId = roomTypeId;
        this.checkIn = checkIn;
        this.checkOut = checkOut;
        this.roomCount = roomCount;
        this.userId = userId;
        this.createdAt = Instant.now();
        this.ttl = ttl;
    }

    // All nights from checkIn (inclusive) to checkOut (exclusive)
    // checkIn=Mar 5, checkOut=Mar 8 → [Mar 5, Mar 6, Mar 7] (3 nights)
    public List<LocalDate> getNights() {
        List<LocalDate> nights = new ArrayList<>();
        LocalDate d = checkIn;
        while (d.isBefore(checkOut)) {
            nights.add(d);
            d = d.plusDays(1);
        }
        return nights;
    }

    public boolean isExpired() {
        return Instant.now().isAfter(createdAt.plus(ttl));
    }

    public String getHoldId()   { return holdId; }
    public String getHotelId()  { return hotelId; }
    public String getRoomTypeId() { return roomTypeId; }
    public int getRoomCount()   { return roomCount; }
    public String getUserId()   { return userId; }
    public LocalDate getCheckIn()  { return checkIn; }
    public LocalDate getCheckOut() { return checkOut; }
}

record Booking(String bookingId, String userId, String hotelId,
               String roomTypeId, LocalDate checkIn, LocalDate checkOut,
               int roomCount, long totalAmount,
               String cancellationPolicyId, BookingStatus status,
               Instant createdAt) {}

class Inventory {
    // Key: (hotelId, roomTypeId) as a concatenated string
    // Value: date → count
    private final Map<String, Map<LocalDate, Integer>> bookedCounts = new ConcurrentHashMap<>();
    private final Map<String, Map<LocalDate, Integer>> heldCounts = new ConcurrentHashMap<>();
    private final ReentrantLock lock = new ReentrantLock();

    private String key(String hotelId, String roomTypeId) {
        return hotelId + ":" + roomTypeId;
    }

    // ── getAvailable for a single date ──
    public int getAvailable(String hotelId, String roomTypeId,
                             LocalDate date, RoomType roomType) {
        lock.lock();
        try {
            String k = key(hotelId, roomTypeId);
            int booked = bookedCounts.getOrDefault(k, Map.of()).getOrDefault(date, 0);
            int held = heldCounts.getOrDefault(k, Map.of()).getOrDefault(date, 0);
            return roomType.overbookedCapacity() - booked - held;
        } finally {
            lock.unlock();
        }
    }

    // ── Available for every night in the range ──
    public int getAvailableForRange(String hotelId, String roomTypeId,
                                     List<LocalDate> nights, RoomType roomType) {
        lock.lock();
        try {
            int minAvailable = Integer.MAX_VALUE;
            for (LocalDate d : nights) {
                int avail = getAvailable(hotelId, roomTypeId, d, roomType);
                minAvailable = Math.min(minAvailable, avail);
            }
            return minAvailable;
        } finally {
            lock.unlock();
        }
    }

    // ── Atomic multi-night hold ──────────
    // Two-phase inside the lock: validate all nights, then mutate all nights.
    public boolean tryHold(String hotelId, String roomTypeId,
                           List<LocalDate> nights, int count, RoomType roomType) {
        lock.lock();
        try {
            String k = key(hotelId, roomTypeId);
            Map<LocalDate, Integer> bookedMap = bookedCounts.computeIfAbsent(k, x -> new HashMap<>());
            Map<LocalDate, Integer> heldMap = heldCounts.computeIfAbsent(k, x -> new HashMap<>());

            // Phase 1: validate ALL nights have capacity
            for (LocalDate d : nights) {
                int booked = bookedMap.getOrDefault(d, 0);
                int held = heldMap.getOrDefault(d, 0);
                if (booked + held + count > roomType.overbookedCapacity()) {
                    return false; // insufficient — no mutations
                }
            }

            // Phase 2: commit — increment held for every night
            for (LocalDate d : nights) {
                heldMap.merge(d, count, Integer::sum);
            }
            return true;
        } finally {
            lock.unlock();
        }
    }

    // ── Confirm: held → booked ──
    public void confirmHold(String hotelId, String roomTypeId,
                             List<LocalDate> nights, int count) {
        lock.lock();
        try {
            String k = key(hotelId, roomTypeId);
            Map<LocalDate, Integer> heldMap = heldCounts.getOrDefault(k, Map.of());
            Map<LocalDate, Integer> bookedMap = bookedCounts.computeIfAbsent(k, x -> new HashMap<>());

            for (LocalDate d : nights) {
                Integer h = heldMap.get(d);
                if (h == null || h < count)
                    throw new IllegalStateException(
                        "Hold no longer valid for " + d);
            }
            // Commit
            for (LocalDate d : nights) {
                heldMap.merge(d, -count, Integer::sum);
                bookedMap.merge(d, count, Integer::sum);
            }
        } finally {
            lock.unlock();
        }
    }

    // ── Release a hold (TTL expiry or cancel before confirm) ──
    public void releaseHold(String hotelId, String roomTypeId,
                             List<LocalDate> nights, int count) {
        lock.lock();
        try {
            String k = key(hotelId, roomTypeId);
            Map<LocalDate, Integer> heldMap = heldCounts.getOrDefault(k, Map.of());
            for (LocalDate d : nights) {
                heldMap.merge(d, -count, Integer::sum);
            }
        } finally {
            lock.unlock();
        }
    }

    // ── Release a confirmed booking (cancellation) ──
    public void cancelBooking(String hotelId, String roomTypeId,
                               List<LocalDate> nights, int count) {
        lock.lock();
        try {
            String k = key(hotelId, roomTypeId);
            Map<LocalDate, Integer> bookedMap = bookedCounts.getOrDefault(k, Map.of());
            for (LocalDate d : nights) {
                bookedMap.merge(d, -count, Integer::sum);
            }
        } finally {
            lock.unlock();
        }
    }
}

interface CancellationPolicy {
    // Returns refund amount in cents. 0 = non-refundable.
    long calculateRefund(Booking booking, Instant cancelTime);
}

class FreeCancellation24h implements CancellationPolicy {
    @Override
    public long calculateRefund(Booking booking, Instant cancelTime) {
        // Free cancellation if cancelling > 24h before check-in
        Instant cutoff = booking.checkIn().atStartOfDay(ZoneId.systemDefault())
            .toInstant().minus(Duration.ofHours(24));
        if (cancelTime.isBefore(cutoff)) return booking.totalAmount();
        return 0;
    }
}

class NonRefundable implements CancellationPolicy {
    @Override
    public long calculateRefund(Booking booking, Instant cancelTime) {
        return 0; // no refund ever
    }
}

class PartialRefundPolicy implements CancellationPolicy {
    @Override
    public long calculateRefund(Booking booking, Instant cancelTime) {
        Instant checkInInstant = booking.checkIn().atStartOfDay(ZoneId.systemDefault()).toInstant();
        Duration untilCheckIn = Duration.between(cancelTime, checkInInstant);

        if (untilCheckIn.toDays() >= 7)   return booking.totalAmount();        // full refund
        if (untilCheckIn.toDays() >= 3)   return booking.totalAmount() / 2;    // 50%
        if (untilCheckIn.toHours() >= 24) return booking.totalAmount() / 4;    // 25%
        return 0;
    }
}

class BookingService {
    private static final Duration HOLD_TTL = Duration.ofMinutes(10);

    private final Map<String, Hotel> hotels = new ConcurrentHashMap<>();
    private final Inventory inventory = new Inventory();
    private final ConcurrentHashMap<String, Hold> holds = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Booking> bookings = new ConcurrentHashMap<>();
    private final Map<String, CancellationPolicy> policies = Map.of(
        "free24h",       new FreeCancellation24h(),
        "non-refundable", new NonRefundable(),
        "partial",       new PartialRefundPolicy()
    );
    private final PaymentService paymentService;
    private final ScheduledExecutorService cleanupScheduler;

    public BookingService(PaymentService paymentService) {
        this.paymentService = paymentService;
        this.cleanupScheduler = Executors.newSingleThreadScheduledExecutor();
        cleanupScheduler.scheduleAtFixedRate(
            this::cleanupExpiredHolds, 30, 30, TimeUnit.SECONDS);
    }

    // ── Search ───────────────────────────
    public List<Hotel> search(String city, LocalDate checkIn, LocalDate checkOut, int guests) {
        validateDateRange(checkIn, checkOut);
        List<LocalDate> nights = toNights(checkIn, checkOut);

        return hotels.values().stream()
            .filter(h -> h.city().equalsIgnoreCase(city))
            .filter(h -> h.roomTypes().values().stream().anyMatch(rt ->
                inventory.getAvailableForRange(h.hotelId(), rt.roomTypeId(), nights, rt) > 0))
            .toList();
    }

    // ── Availability query ───────────────
    public int getAvailability(String hotelId, String roomTypeId,
                                LocalDate checkIn, LocalDate checkOut) {
        validateDateRange(checkIn, checkOut);
        Hotel hotel = hotels.get(hotelId);
        if (hotel == null) throw new HotelNotFoundException(hotelId);
        RoomType rt = hotel.roomTypes().get(roomTypeId);
        if (rt == null) throw new RoomTypeNotFoundException(roomTypeId);

        return inventory.getAvailableForRange(hotelId, roomTypeId, toNights(checkIn, checkOut), rt);
    }

    // ── holdRooms (atomic multi-night) ──
    public String holdRooms(String hotelId, String roomTypeId,
                             LocalDate checkIn, LocalDate checkOut,
                             int count, String userId) {
        validateDateRange(checkIn, checkOut);
        if (count <= 0) throw new IllegalArgumentException("count must be positive");

        Hotel hotel = hotels.get(hotelId);
        if (hotel == null) throw new HotelNotFoundException(hotelId);
        RoomType rt = hotel.roomTypes().get(roomTypeId);
        if (rt == null) throw new RoomTypeNotFoundException(roomTypeId);

        List<LocalDate> nights = toNights(checkIn, checkOut);

        if (!inventory.tryHold(hotelId, roomTypeId, nights, count, rt))
            throw new NoAvailabilityException("Not enough rooms for the date range");

        Hold hold = new Hold(hotelId, roomTypeId, checkIn, checkOut, count, userId, HOLD_TTL);
        holds.put(hold.getHoldId(), hold);
        return hold.getHoldId();
    }

    // ── Confirm booking ──────────────────
    public Booking confirmBooking(String holdId, String paymentToken, String policyId) {
        Hold hold = holds.get(holdId);
        if (hold == null) throw new InvalidHoldException("Hold not found");

        if (hold.isExpired()) {
            inventory.releaseHold(hold.getHotelId(), hold.getRoomTypeId(),
                hold.getNights(), hold.getRoomCount());
            holds.remove(holdId);
            throw new HoldExpiredException("Hold expired, please retry");
        }

        Hotel hotel = hotels.get(hold.getHotelId());
        RoomType rt = hotel.roomTypes().get(hold.getRoomTypeId());
        long nightsCount = hold.getNights().size();
        long total = rt.basePriceCents() * nightsCount * hold.getRoomCount();

        if (!paymentService.charge(hold.getUserId(), total, paymentToken)) {
            // Payment failed — keep the hold alive (user may retry with different card)
            throw new PaymentFailedException("Payment declined");
        }

        try {
            inventory.confirmHold(hold.getHotelId(), hold.getRoomTypeId(),
                hold.getNights(), hold.getRoomCount());
        } catch (IllegalStateException e) {
            // Rare: hold expired between our check and confirmation. Refund.
            paymentService.refund(hold.getUserId(), total);
            throw new HoldExpiredException("Hold invalidated during confirmation");
        }

        Booking booking = new Booking(
            UUID.randomUUID().toString(),
            hold.getUserId(),
            hold.getHotelId(),
            hold.getRoomTypeId(),
            hold.getCheckIn(),
            hold.getCheckOut(),
            hold.getRoomCount(),
            total,
            policyId,
            BookingStatus.CONFIRMED,
            Instant.now());
        bookings.put(booking.bookingId(), booking);
        holds.remove(holdId);
        return booking;
    }

    // ── cancelBooking ───────────────────
    public long cancelBooking(String bookingId) {
        Booking booking = bookings.get(bookingId);
        if (booking == null) throw new IllegalArgumentException("Booking not found");
        if (booking.status() != BookingStatus.CONFIRMED)
            throw new IllegalStateException("Already cancelled");

        CancellationPolicy policy = policies.get(booking.cancellationPolicyId());
        if (policy == null) policy = new NonRefundable(); // fallback
        long refund = policy.calculateRefund(booking, Instant.now());

        // Release inventory
        List<LocalDate> nights = toNights(booking.checkIn(), booking.checkOut());
        inventory.cancelBooking(booking.hotelId(), booking.roomTypeId(),
            nights, booking.roomCount());

        // Process refund (if any)
        if (refund > 0) paymentService.refund(booking.userId(), refund);

        // Update booking status
        bookings.put(bookingId, new Booking(
            booking.bookingId(), booking.userId(), booking.hotelId(),
            booking.roomTypeId(), booking.checkIn(), booking.checkOut(),
            booking.roomCount(), booking.totalAmount(),
            booking.cancellationPolicyId(), BookingStatus.CANCELLED,
            booking.createdAt()));

        return refund;
    }

    // ── Background cleanup ───────────────
    private void cleanupExpiredHolds() {
        holds.forEach((id, hold) -> {
            if (hold.isExpired()) {
                inventory.releaseHold(hold.getHotelId(), hold.getRoomTypeId(),
                    hold.getNights(), hold.getRoomCount());
                holds.remove(id);
            }
        });
    }

    // ── Helpers ──────────────────────────
    private void validateDateRange(LocalDate checkIn, LocalDate checkOut) {
        if (checkIn == null || checkOut == null)
            throw new IllegalArgumentException("dates required");
        if (!checkOut.isAfter(checkIn))
            throw new InvalidDateRangeException("checkOut must be after checkIn");
        if (checkIn.isBefore(LocalDate.now()))
            throw new InvalidDateRangeException("checkIn must be in the future");
    }

    private List<LocalDate> toNights(LocalDate checkIn, LocalDate checkOut) {
        List<LocalDate> nights = new ArrayList<>();
        LocalDate d = checkIn;
        while (d.isBefore(checkOut)) {
            nights.add(d);
            d = d.plusDays(1);
        }
        return nights;
    }
}

interface PaymentService {
    boolean charge(String userId, long amount, String token);
    void refund(String userId, long amount);
}
